(()=>{
let active='football',view='',homeIndex=0,opening=false,pendingEntrance=false,suppressHomeClick=0;
const sportKeys=Object.keys(SPORTS),state={down:1,pos:25,target:35,team:'우리',ended:false,rotation:0,penalties:0};
const main=document.querySelector('main'),nav=document.querySelector('#navigation'),dialog=document.querySelector('dialog');
const reduceMotion=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
function syncSelection(sport){active=sport;const d=SPORTS[sport];document.documentElement.style.setProperty('--accent',d.color);document.documentElement.style.setProperty('--tint',d.tint);document.title=d.name+' · Rule Book for Watching';if(!nav.innerHTML)nav.innerHTML=`<div class="nav-wrap"><nav aria-label="종목 이동">${sportKeys.map(k=>`<a href="#/${k}" data-nav-sport="${k}">${SPORTS[k].name}</a>`).join('')}</nav></div>`;nav.querySelectorAll('[data-nav-sport]').forEach(a=>{const selected=a.dataset.navSport===sport;a.classList.toggle('active',selected);if(selected)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});}
function updateHomePosition(){const stage=main.querySelector('.entry-stage');if(!stage)return;stage.style.setProperty('--drag-x','0px');stage.querySelector('.entry-window').scrollLeft=0;stage.querySelectorAll('.entry-slide').forEach((slide,i)=>{const current=i===homeIndex;slide.style.setProperty('--offset',i-homeIndex);slide.classList.toggle('is-current',current);slide.inert=!current;slide.setAttribute('aria-hidden',String(!current));slide.querySelector('a').tabIndex=current?0:-1;});stage.querySelector('.entry-prev').disabled=homeIndex===0;stage.querySelector('.entry-next').disabled=homeIndex===sportKeys.length-1;stage.querySelector('.entry-position').textContent=`${homeIndex+1} / ${sportKeys.length} · ${SPORTS[sportKeys[homeIndex]].name}`;syncSelection(sportKeys[homeIndex]);}
function moveHome(delta){if(view!=='home'||opening)return;const next=Math.max(0,Math.min(sportKeys.length-1,homeIndex+delta));if(next===homeIndex)return;homeIndex=next;history.replaceState(null,'','#/'+sportKeys[homeIndex]);updateHomePosition();}
function setupHome(){const stage=main.querySelector('.entry-stage');let pointer=null,wheelLast=0,wheelTotal=0,wheelLock=0;stage.addEventListener('wheel',e=>{if(e.ctrlKey||e.metaKey)return;e.preventDefault();const now=performance.now();if(pointer||now<wheelLock||opening)return;if(now-wheelLast>160)wheelTotal=0;wheelLast=now;const delta=Math.abs(e.deltaX)>Math.abs(e.deltaY)?e.deltaX:e.deltaY;wheelTotal+=delta*(e.deltaMode===1?16:e.deltaMode===2?innerWidth:1);if(Math.abs(wheelTotal)<38)return;moveHome(wheelTotal>0?1:-1);wheelTotal=0;wheelLock=now+550;},{passive:false});
stage.addEventListener('pointerdown',e=>{if(e.button!==0||opening||e.target.closest('.entry-arrow'))return;pointer={id:e.pointerId,x:e.clientX,y:e.clientY,moved:false};});stage.addEventListener('pointermove',e=>{if(!pointer||pointer.id!==e.pointerId)return;const dx=e.clientX-pointer.x;if(!pointer.moved&&Math.abs(dx)>8&&Math.abs(dx)>Math.abs(e.clientY-pointer.y)){pointer.moved=true;stage.setPointerCapture(e.pointerId);}if(pointer.moved){stage.classList.add('is-dragging');const edge=homeIndex===0&&dx>0||homeIndex===sportKeys.length-1&&dx<0;stage.style.setProperty('--drag-x',dx*(edge?.2:.8)+'px');}});
function finish(e){if(!pointer||pointer.id!==e.pointerId)return;const dx=e.clientX-pointer.x;if(pointer.moved){suppressHomeClick=performance.now()+400;if(e.type!=='pointercancel'&&Math.abs(dx)>Math.min(80,innerWidth*.16))moveHome(dx<0?1:-1);}if(stage.hasPointerCapture(e.pointerId))stage.releasePointerCapture(e.pointerId);pointer=null;stage.classList.remove('is-dragging');updateHomePosition();}stage.addEventListener('pointerup',finish);stage.addEventListener('pointercancel',finish);stage.addEventListener('dragstart',e=>e.preventDefault());updateHomePosition();}
async function openCourse(a){if(opening||performance.now()<suppressHomeClick)return;opening=true;const hash=location.hash,r=a.getBoundingClientRect(),m=main.getBoundingClientRect();main.style.transformOrigin=`${r.x+r.width/2-m.x}px ${r.y+r.height/2-m.y}px`;if(!reduceMotion()){const exit=main.animate([{opacity:1,transform:'translateY(0) scale(1)'},{opacity:0,transform:'translateY(-22vh) scale(1.045)'}],{duration:260,easing:'cubic-bezier(.4,0,.7,1)',fill:'forwards'});try{await exit.finished;}catch{}if(location.hash===hash)main.style.visibility='hidden';exit.cancel();}if(location.hash!==hash){opening=false;main.style.visibility='';main.style.transformOrigin='';return;}pendingEntrance=true;location.hash=a.getAttribute('href');}
function render(){let [,route='home',section,anchor]=location.hash.split('/');const isHome=!SPORTS[route]||!section,sport=SPORTS[route]?route:(SPORTS[section]?section:sportKeys[homeIndex]),detailAnchor=section==='guide'?anchor:section,nextView=isHome?'home':sport,changed=view!==nextView||!main.innerHTML;homeIndex=sportKeys.indexOf(sport);view=nextView;document.body.classList.toggle('entry-view',isHome);syncSelection(sport);if(isHome&&location.hash!=='#/'+sport)history.replaceState(null,'','#/'+sport);
if(changed){main.getAnimations().forEach(a=>a.cancel());main.style.visibility='';main.style.transformOrigin='';main.innerHTML=isHome?UI.home():`<a class="back-to-cards" href="#/${sport}">‹ 종목 카드로</a>`+UI.sport(sport);Object.assign(state,{down:1,pos:25,target:35,team:'우리',ended:false,rotation:0,penalties:0});if(isHome)setupHome();else if(sport==='football')updateDown(main.querySelector('[data-sim="down"]'),0,true);}else if(isHome)updateHomePosition();
if(!isHome&&detailAnchor)requestAnimationFrame(()=>document.getElementById(detailAnchor)?.scrollIntoView({behavior:'auto',block:'start'}));else window.scrollTo(0,0);
if(pendingEntrance&&!isHome){pendingEntrance=false;opening=false;if(!reduceMotion())main.animate([{opacity:0,transform:'translateY(34vh)'},{opacity:1,transform:'translateY(0)'}],{duration:620,easing:'cubic-bezier(.16,1,.3,1)'});main.querySelector('.sport-heading h1').setAttribute('tabindex','-1');main.querySelector('.sport-heading h1').focus({preventScroll:true});}else opening=false;
}
new ResizeObserver(()=>document.documentElement.style.setProperty('--header-height',nav.getBoundingClientRect().height+'px')).observe(nav);
window.addEventListener('keydown',e=>{if(view!=='home'||opening||e.altKey||e.metaKey||e.ctrlKey||e.target.matches('input,textarea,select'))return;if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();moveHome(e.key==='ArrowRight'?1:-1);if(e.target.closest('.entry-slide'))main.querySelector('.entry-slide.is-current a').focus({preventScroll:true});}});

function popup(t,p){dialog.querySelector('.zoom-content')?.remove();dialog.classList.remove('large');dialog.querySelector('h2').textContent=t;dialog.querySelector('p').textContent=p;dialog.showModal();}
dialog.querySelector('button').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close();});
function selected(box,btn){box.querySelectorAll('.controls button').forEach(b=>{b.classList.toggle('selected',b===btn);b.setAttribute('aria-pressed',String(b===btn));});}
function updateDown(box,gain,reset=false){if(reset)Object.assign(state,{down:1,pos:25,target:35,team:'우리',ended:false});else if(state.ended)return;else{state.pos+=gain;if(state.pos>=100){state.pos=100;state.ended=true;state.message=state.team+' 팀 Touchdown +6. 추가 시도를 선택합니다.';}else if(state.pos<=0){state.pos=0;state.ended=true;state.message='자기 엔드존에서 다운 → 상대 팀 Safety +2.';}else if(state.pos>=state.target){state.down=1;state.target=Math.min(100,state.pos+10);state.message='목표 도달! 새로운 1st down.';}else if(state.down===4){state.team=state.team==='우리'?'상대':'우리';state.pos=100-state.pos;state.down=1;state.target=Math.min(100,state.pos+10);state.message='4th down 미달 → 공격권 변경. 위치는 상대 시점으로 바뀝니다.';}else{state.down++;state.message=gain<0?'뒤로 밀려 목표까지 더 멀어졌습니다.':'다음 다운에도 목표선은 그대로입니다.';}}
const label=state.ended?(state.pos===100?'TOUCHDOWN':'SAFETY'):`${['','1st','2nd','3rd','4th'][state.down]} & ${state.target===100?'Goal':state.target-state.pos}`;box.querySelector('.display').textContent=label;box.querySelector('.live-text').textContent=`${state.team} 팀 ${state.pos<=50?'자기 '+state.pos:'상대 '+(100-state.pos)}야드 · ${reset?'우리 25야드에서 다시 시작합니다.':state.message}`;box.querySelectorAll('[data-action="gain"]').forEach(b=>b.disabled=state.ended);
const pos=100+state.pos*6,target=100+state.target*6;box.querySelector('.sim-diagram').innerHTML=UI.diagram(`<svg viewBox="0 0 800 190" role="img" aria-label="현재 공 위치 ${state.pos}야드, 목표 ${state.target}야드"><rect x="40" y="40" width="720" height="85" fill="#dcefe3"/><rect x="40" y="40" width="60" height="85" fill="#9cc0ab"/><rect x="700" y="40" width="60" height="85" fill="#9cc0ab"/><line x1="${pos}" y1="25" x2="${pos}" y2="140" stroke="#2878c1" stroke-width="3"/><line x1="${target}" y1="25" x2="${target}" y2="140" stroke="#c59d18" stroke-width="3" stroke-dasharray="8 5"/><circle cx="${pos}" cy="83" r="9" fill="#d7524d"/><text x="100" y="167">자기 0</text><text x="365" y="167">중앙 50</text><text x="685" y="167">상대 0</text></svg>`,'파랑 = 현재 스냅 위치 · 노랑 점선 = 목표선. 시리즈 중 목표선은 고정됩니다.');}
main.addEventListener('click',e=>{const arrow=e.target.closest('[data-carousel]');if(arrow){moveHome(arrow.dataset.carousel==='next'?1:-1);return;}const course=e.target.closest('[data-open-sport]');if(course){if(e.ctrlKey||e.metaKey||e.shiftKey||e.altKey)return;e.preventDefault();if(performance.now()>=suppressHomeClick)openCourse(course);return;}const role=e.target.closest('[data-role]');if(role){const name=role.dataset.role;const all=SPORTS[active]?.sections.flatMap(s=>s.cards).flatMap(c=>c.roles||[])||[];const match=all.find(([t])=>t.split(' ')[0]===name.split(' ')[0]);popup(name,match?.[1]||name+' — 배치는 전술에 따른 예시입니다. 포지션과 역할 표에서 자세히 확인하세요.');return;}
const term=e.target.closest('[data-term]');if(term){popup(term.dataset.term,term.dataset.description);return;}
const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action,box=b.closest('.simulation'),value=b.dataset.value;
if(action==='zoom'){const source=b.closest('.diagram').querySelector('svg');popup('그림 크게 보기','좌우로 움직여 상세 표시를 보세요.');let zoom=document.createElement('div');zoom.className='zoom-content';zoom.innerHTML=source.outerHTML;dialog.append(zoom);dialog.classList.add('large');return;}
if(action==='compare'){const area=b.closest('.comparison-block');selected(area,b);area.querySelector('.compare-diagram').innerHTML=UI.diagram(Diagrams.compare(area.dataset.kind,value==='bad'));}
if(action==='formation'){selected(box,b);box.querySelector('.sim-diagram').innerHTML=UI.diagram(Diagrams.defense(value));}
if(action==='gain'||action==='reset-down')updateDown(box,Number(value)||0,action==='reset-down');
if(action==='ruck'){selected(box,b);box.querySelector('.sim-diagram').innerHTML=UI.diagram(Diagrams.ruck(Number(value)));box.querySelector('.live-text').textContent=['태클된 선수는 공을 즉시 놓고, 태클러는 놓아주고 비킵니다.','양 팀 서 있는 선수가 바닥 공 위에 접촉해 럭 형성. 옆 진입·원칙적 손 사용 금지.','공이 럭 밖으로 나와 9번이 10번에게 연결합니다.','합법 위치에서 기다리던 수비가 전진합니다. 기존 offside 선수는 회복 의무가 남습니다.'][Number(value)];}
if(['rotate','hold-serve','reset-rotation'].includes(action)){if(action==='rotate')state.rotation=(state.rotation+1)%6;if(action==='reset-rotation')state.rotation=0;box.querySelector('.sim-diagram').innerHTML=UI.diagram(Diagrams.rotation(state.rotation));const order=[2,1,6,5,4,3];const p=order[(order.indexOf(1)-state.rotation+6)%6];box.querySelector('.live-text').textContent=(action==='hold-serve'?'서브 유지 득점: 회전하지 않습니다. ':'회전 상태: '+state.rotation+'칸. ')+`현재 1번의 P${p}가 서브합니다.`;}
if(action.startsWith('penalty-')){if(action==='penalty-add')state.penalties++;if(action==='penalty-reset')state.penalties=0;if(action==='penalty-end'||action==='penalty-goal')state.penalties=Math.max(0,state.penalties-1);const n=Math.max(3,5-state.penalties),q=Math.max(0,state.penalties-2);box.querySelector('.display').textContent='5-on-'+n;box.querySelector('.sim-diagram').innerHTML=UI.diagram(Diagrams.penalty(state.penalties));box.querySelector('.live-text').textContent=`박스 ${state.penalties}명 · 진행 중 ${Math.min(2,state.penalties)}개 · 시작 대기 ${q}개. `+(action==='penalty-goal'?'학습 가정상 종료 가능한 minor 하나 종료. ':'')+(q?'최소 3명 유지. 추가 minor는 앞선 벌칙 종료를 기다립니다.':'');}
if(action==='polo'){selected(box,b);box.querySelector('.sim-diagram').innerHTML=UI.diagram(Diagrams.poloLine(value==='danger'));box.querySelector('.live-text').textContent=value==='danger'?'코앞을 가로지르는 위험한 교차 진입은 반칙이 될 수 있습니다.':'같은 방향에서 충분한 거리로 접근하면 ride-off·hook 수비가 가능합니다.';}
});
main.addEventListener('keydown',e=>{if(e.target.matches('[data-role]')&&(e.key==='Enter'||e.key===' ')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
window.addEventListener('hashchange',render);render();
})();
